+// API keys, role permissions and the audit log of data changes.
+import { AppError } from "../errors.js";
+
+export const ROLES = ["viewer", "cook", "manager"];
+
+const COOK_WRITES = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+/** Finds the API key for an Authorization header ("Bearer <key>"), or throws unauthorized. */
+export function authenticate(store, header) {
+  if (typeof header !== "string" || !header.startsWith("Bearer ")) throw new AppError("unauthorized");
+  const token = header.slice(7).trim();
+  if (!token) throw new AppError("unauthorized");
+  const apiKey = (store.data.apiKeys ?? []).find((k) => k.key === token);
+  if (!apiKey) throw new AppError("unauthorized");
+  return apiKey;
+}
+
+/** Checks that `apiKey` has permission for `method` and `path`, or throws forbidden. */
+export function authorize(apiKey, method, path) {
+  if (!apiKey || !ROLES.includes(apiKey.role)) throw new AppError("forbidden");
+  if (apiKey.role === "manager") return;
+  if (path === "/audit" || path.startsWith("/audit/")) throw new AppError("forbidden");
+  if (apiKey.role === "viewer" && method === "GET") return;
+  if (apiKey.role === "cook") {
+    if (method === "GET") return;
+    if (COOK_WRITES.some(([m, re]) => m === method && re.test(path))) return;
+  }
+  throw new AppError("forbidden");
+}
+
+/** Appends an audit entry for a request that changed data. */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].reverse().sort((a, b) => b.at.localeCompare(a.at));
+}
